    coords = getv(instance, "coords", None)
    if coords is None:
        coords = getv(instance, "coordinates", None)
    if coords is None:
        coords = getv(instance, "locations", None)

    dm = getv(instance, "distance_matrix", None)
    if dm is None:
        dm = getv(instance, "distances", None)

    if isinstance(demands, dict):
        customers = [k for k in demands.keys() if k != depot]
    elif isinstance(demands, list):
        customers = [i for i in range(len(demands)) if i != depot]
    elif coords is not None:
        customers = [i for i in range(len(coords)) if i != depot]
    elif dm is not None:
        customers = [i for i in range(len(dm)) if i != depot]
    else:
        customers = []
    customers = sorted(customers)

    def demand_of(i):
        if demands is None:
            return 1
        if isinstance(demands, dict):
            return demands.get(i, 1)
        if 0 <= i < len(demands):
            return demands[i]
        return 1

    def dist(i, j):
        if i == j:
            return 0.0
        if dm is not None:
            try:
                return dm[i][j]
            except Exception:
                return dm[int(i)][int(j)]
        if coords is not None:
            a = coords[i]
            b = coords[j]
            dx = a[0] - b[0]
            dy = a[1] - b[1]
            return (dx * dx + dy * dy) ** 0.5
        return abs(i - j)

    depot_xy = coords[depot] if coords is not None else (0.0, 0.0)

    def ang_key(i):
        if coords is None:
            return (0, i)
        p = coords[i]
        dx = p[0] - depot_xy[0]
        dy = p[1] - depot_xy[1]
        if dx >= 0 and dy >= 0:
            q = 0
            t = dy / (dx + 1e-12)
        elif dx < 0 <= dy:
            q = 1
            t = (-dx) / (dy + 1e-12)
        elif dx <= 0 and dy < 0:
            q = 2
            t = (-dy) / ((-dx) + 1e-12)
        else:
            q = 3
            t = dx / ((-dy) + 1e-12)
        return (q, t, dx * dx + dy * dy, i)

    def route_load(r):
        s = 0
        for c in r:
            s += demand_of(c)
        return s

    def route_cost(r):
        if not r:
            return 0.0
        c = dist(depot, r[0])
        for a, b in zip(r, r[1:]):
            c += dist(a, b)
        return c + dist(r[-1], depot)

    def insert_best(route, c):
        n = len(route)
        best_pos = 0
        best_delta = None
        for p in range(n + 1):
            if n == 0:
                delta = 2 * dist(depot, c)
            elif p == 0:
                delta = dist(depot, c) + dist(c, route[0]) - dist(depot, route[0])
            elif p == n:
                delta = dist(route[-1], c) + dist(c, depot) - dist(route[-1], depot)
            else:
                a = route[p - 1]
                b = route[p]
                delta = dist(a, c) + dist(c, b) - dist(a, b)
            if best_delta is None or delta < best_delta - 1e-12 or (abs(delta - best_delta) <= 1e-12 and p < best_pos):
                best_delta = delta
                best_pos = p
        return best_pos

    def two_opt(r):
        n = len(r)
        if n < 4:
            return r[:]
        r = r[:]
        improved = True
        while improved:
            improved = False
            best_i = -1
            best_j = -1
            best_gain = 0.0
            for i in range(n - 2):
                a = depot if i == 0 else r[i - 1]
                b = r[i]
                for j in range(i + 2, n):
                    c = r[j - 1]
                    d = depot if j == n else r[j]
                    gain = (dist(a, b) + dist(c, d)) - (dist(a, c) + dist(b, d))
                    if gain > best_gain + 1e-12:
                        best_gain = gain
                        best_i = i
                        best_j = j
            if best_gain > 1e-12:
                r = r[:best_i] + r[best_i:best_j][::-1] + r[best_j:]
                improved = True
        return r

    ordered = sorted(customers, key=ang_key)
    routes = []
    cur = []
    cur_load = 0
    for c in ordered:
        d = demand_of(c)
        if d > capacity:
            if cur:
                routes.append(cur)
                cur = []
                cur_load = 0
            routes.append([c])
        elif cur_load + d <= capacity:
            cur.append(c)
            cur_load += d
        else:
            if cur:
                routes.append(cur)
            cur = [c]
            cur_load = d
    if cur:
        routes.append(cur)

    for i in range(len(routes)):
        r = routes[i]
        seq = []
        for c in r:
            pos = insert_best(seq, c)
            seq = seq[:pos] + [c] + seq[pos:]
        routes[i] = two_opt(seq)

    # minor deterministic improvement by relocating within route ordering
    for _ in range(3):
        changed = False
        for i in range(len(routes)):
            r = routes[i]
            if len(r) < 3:
                continue
            best = r
            best_cost = route_cost(r)
            for a in range(len(r)):
                x = r[:a] + r[a + 1:]
                for p in range(len(x) + 1):
                    cand = x[:p] + [r[a]] + x[p:]
                    cc = route_cost(cand)
                    if cc + 1e-12 < best_cost:
                        best = cand
                        best_cost = cc
            if best != r:
                routes[i] = two_opt(best)
                changed = True
        if not changed:
            break

    seen = set()
    fixed = []
    for r in routes:
        nr = []
        load = 0
        for c in r:
            if c != depot and c not in seen:
                d = demand_of(c)
                if load + d <= capacity:
                    nr.append(c)
                    seen.add(c)
                    load += d
        if nr:
            fixed.append(nr)
    missing = [c for c in customers if c not in seen]
    for c in missing:
        placed = False
        for r in fixed:
            if route_load(r) + demand_of(c) <= capacity:
                r.insert(insert_best(r, c), c)
                placed = True
                break
        if not placed:
            fixed.append([c])

    return [two_opt(r) for r in fixed if r]
